// edges hold {u, v, w}. Fills dist; returns false on a negative cycle.
bool bellmanFord(int n, vector<array<int,3>>& edges, int src,
                 vector<long long>& dist) {
    const long long INF = 1e18;
    dist.assign(n, INF); dist[src] = 0;
    for (int it = 0; it < n - 1; ++it)              // V-1 relaxation rounds
        for (auto& e : edges)
            if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]])
                dist[e[1]] = dist[e[0]] + e[2];
    for (auto& e : edges)                            // extra round detects cycle
        if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]])
            return false;
    return true;
}

def bellman_ford(n, edges, src):
    INF = float('inf')
    dist = [INF]*n; dist[src] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:                 # extra round
        if dist[u] != INF and dist[u] + w < dist[v]:
            return None                   # negative cycle
    return dist
